import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"豐","description":"焦氏易林注 - 豐","frontmatter":{"title":"豐","description":"焦氏易林注 - 豐"},"headers":[],"relativePath":"classics/jiaoyilin/055.md","filePath":"classics/jiaoyilin/055.md"}'),l={name:"classics/jiaoyilin/055.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="豐" tabindex="-1">豐 <a class="header-anchor" href="#豐" aria-label="Permalink to “豐”">​</a></h1><h3 id="豐-1" tabindex="-1">豐 <a class="header-anchor" href="#豐-1" aria-label="Permalink to “豐”">​</a></h3><h3 id="豐之乾" tabindex="-1">豐之乾 <a class="header-anchor" href="#豐之乾" aria-label="Permalink to “豐之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>鼎足承德，嘉謀生福。為王開庭，得心所欲。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《晉》之《大壯》。</p><h3 id="豐之坤" tabindex="-1">豐之坤 <a class="header-anchor" href="#豐之坤" aria-label="Permalink to “豐之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>曳綸江海，釣魴與鯉。王孫列俎，以饗仲友。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此用豐卦。互巽為綸，兌為江海，巽為魚，故曰魴鯉。伏艮為王孫，伏震為俎，兌食，故曰饗。兌為朋友，伏坎，故曰仲友。○列俎，宋元本作利得，皆形訛字，依汲古。第二句宋元本作釣掛魴鯉，依汲古。</p><h3 id="豐之屯" tabindex="-1">豐之屯 <a class="header-anchor" href="#豐之屯" aria-label="Permalink to “豐之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>東山皋落，叛逆不服。興師徵討，恭子敗覆。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮山，震東，皋亦小山，故曰東山皋落。皋落，赤狄別種。坤為叛逆、為師，震為徵討、為子，坤順，故曰恭子。坤為敗覆，恭子，太子申生也。閔二年晉侯使太子申生伐東山皋落氏，後申生卒被譖死。</p><h3 id="豐之蒙" tabindex="-1">豐之蒙 <a class="header-anchor" href="#豐之蒙" aria-label="Permalink to “豐之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>千里騂駒，為王服車。嘉其麗榮，君子有成。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坤為千里，震馬，故曰千里騂駒。震為王、為車、為榮，艮為君子、為成。為王服車，即為王駕車也。</p><h3 id="豐之需" tabindex="-1">豐之需 <a class="header-anchor" href="#豐之需" aria-label="Permalink to “豐之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>二龍北行，道逢六狼。莫宿中澤，為禍所傷。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>乾為龍，兌卦數二，故曰二龍。坎北，故曰北行。伏艮為道、為狼，坎數六，故曰六狼。坎為莫、為宿，兌為澤，坤為禍。○二，宋本、汲古作三，非，依元本。莫，宋元本作暮，亦非，西漢時多作莫，暮為後人妄改，故依汲古。</p><h3 id="豐之訟" tabindex="-1">豐之訟 <a class="header-anchor" href="#豐之訟" aria-label="Permalink to “豐之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>天災所遊，兇不可居。轉徙獲福，留止危憂。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>乾為天，離為災兇，伏震為轉徙、為福，坎陷，故曰留止。坎為危、為憂也。</p><h3 id="豐之師" tabindex="-1">豐之師 <a class="header-anchor" href="#豐之師" aria-label="Permalink to “豐之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>狐狸雉兔，畏人逃去。分走竄匿，不知所處。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《解》。知，宋元本訛如，非。</p><h3 id="豐之比" tabindex="-1">豐之比 <a class="header-anchor" href="#豐之比" aria-label="Permalink to “豐之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>雨師娶婦，黃巖季女。成禮既婚，相呼南去。膏潤田裡，年歲大喜。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《損》之《益》。女，汲古作子，去作上，均依宋元本。喜，各本皆作有，依《損》之《益》校。田裡，各本皆作下土，依《恆》之《晉》校。</p><h3 id="豐之小畜" tabindex="-1">豐之小畜 <a class="header-anchor" href="#豐之小畜" aria-label="Permalink to “豐之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>外棲野鼠，與雉為伍。瘡痍不息，即去其室。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>伏坎為鼠，離為雉，坎離夫婦，故曰為伍。伏艮為瘡痍，坤死，故不息。坎為室，震為去，言將死而去其室也。○雉，宋元本作雞，依汲古。</p><h3 id="豐之履" tabindex="-1">豐之履 <a class="header-anchor" href="#豐之履" aria-label="Permalink to “豐之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>天命絕後，孤陽無主。旁徨兩社，獨不得酒。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>乾天，巽命，巽下斷，故曰絕。乾陽，巽寡，故陽孤。震為主，震伏，故曰無主。伏坤為社，兌卦數二，故曰兩社。元本註春社、秋社也。坎為酒，坎伏，故不得酒。古者社祭飲食宴樂，故曰得酒，或謂周社亳社亦為兩社，然下曰得酒，似指春秋社祭也。○天，宋元本訛夭。</p><h3 id="豐之泰" tabindex="-1">豐之泰 <a class="header-anchor" href="#豐之泰" aria-label="Permalink to “豐之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>鵠思其雄，欲隨鳳東。順理羽翼，出次須日。中留北邑，復反其室。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《離》。理，宋元本作裡，依汲古。須日中，汲古作日中須，依宋元本。留，元本訛苗。</p><h3 id="豐之否" tabindex="-1">豐之否 <a class="header-anchor" href="#豐之否" aria-label="Permalink to “豐之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>蜲蛇九子，長尾不殆。均明光澤，燕自受福。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>巽為蛇，震數九，故曰九子。艮為尾，巽為長，故曰長尾。乾大明，艮光明，故曰均明光澤。伏兌為燕，乾為福。殆，音以。</p><h3 id="豐之同人" tabindex="-1">豐之同人 <a class="header-anchor" href="#豐之同人" aria-label="Permalink to “豐之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>日走月步，趨不同舍。夫妻反目，君主失國。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《同人》。</p><h3 id="豐之大有" tabindex="-1">豐之大有 <a class="header-anchor" href="#豐之大有" aria-label="Permalink to “豐之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>定房戶室，枯薪除毒。文德淵府，害不能賊。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。艮為星，艮止，故曰定。定，星名也。房方通用，《詩小雅》既方既皂，《鄭箋》方，房也。定方者，離乾皆在南，坎坤皆在北，《墉詩》定之方中，作於楚宮，言定星中四方定可作宮作室也。艮為室，坤為毒、為薪，離為枯。枯薪除毒者，按：《管子》萩室熯造註：熯謂火乾之也。三月之時，陽氣盛發，易生瘟疫，楸樹鬰臭，以闢毒氣，故燒之於新造之室，以為禳祓。枯薪除毒，即此事也。離為文，坤為淵、為府、為害，坎為賊。○定，宋元本作宣，薪作期，茲依汲古。宣字疑為後人所改，謂武帝築宮於瓠子河上，名曰宣房，獨不思下曰除毒，確非治河之事，而祓除之事也。枯，汲古作括，依宋元本。定房戶室應為定方作室，此林皆以詩為本，詩定之方中、作於楚室註：定昏中四方正是也，詩秉心塞淵，茲曰淵府，皆依附詩詞，故知定房必為定方，戶室必為作室，丁宴依宋本作宣房，以為宣房與史記合，豈知宣為訛字，方房通用，然各本皆作房戶，亦不敢竟改為方作論定，以俟知者。</p><h3 id="豐之謙" tabindex="-1">豐之謙 <a class="header-anchor" href="#豐之謙" aria-label="Permalink to “豐之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>齊東郭盧，嫁於洛都。駿美良好，利彼過倍。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《坎》。盧，宋本、汲古作廬，依元本。嫁，往也，見列子。</p><h3 id="豐之豫" tabindex="-1">豐之豫 <a class="header-anchor" href="#豐之豫" aria-label="Permalink to “豐之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>病篤難醫，和不能治。命終期訖，下即蒿里。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《益》。</p><h3 id="豐之隨" tabindex="-1">豐之隨 <a class="header-anchor" href="#豐之隨" aria-label="Permalink to “豐之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>開郭緒業，王跡所起。姬德七百，報以八子。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>定四年武王之母弟八人，又卜年七百。廓，宋本、汲古訛郭，依元本。緒，汲古訛聚，依宋元本。震為開廓、為王、為足，故曰王跡。震為姬，數七，故曰姬德七百。艮數八，故曰八子。</p><h3 id="豐之蠱" tabindex="-1">豐之蠱 <a class="header-anchor" href="#豐之蠱" aria-label="Permalink to “豐之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>豐年多儲，河海饒魚。商客善賈，大國富有。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為年，艮止，故曰儲。巽為魚，兌澤，故曰河海饒魚。巽為商賈，艮為國，震為富。○河，宋元本作江，依汲古。</p><h3 id="豐之臨" tabindex="-1">豐之臨 <a class="header-anchor" href="#豐之臨" aria-label="Permalink to “豐之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>鵠求魚食，過彼射邑。繒加我頸，繳掛羽翼。欲飛不能，為羿所得。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為鵠、為口，坤為魚，故曰鵠求魚食。坤為邑，震為射，故曰射邑。伏巽為繒繳，伏艮為頸，震為羽翼、為飛，坤閉，兌折，故不能飛。坤惡，故曰羿。坤喪，故為所得。</p><h3 id="豐之觀" tabindex="-1">豐之觀 <a class="header-anchor" href="#豐之觀" aria-label="Permalink to “豐之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>望城抱子，見邑不殆。公孫上堂，文君悅喜。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為望、為城、為抱，坤為邑、為文，艮為孫、為堂，伏震為君，故曰文君。伏震為喜，兌為悅。○文，宋元本作大，非，依汲古。悅，元本作歡，依宋本。殆，音以。</p><h3 id="豐之噬嗑" tabindex="-1">豐之噬嗑 <a class="header-anchor" href="#豐之噬嗑" aria-label="Permalink to “豐之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>左指右麾，邪淫侈靡。執節無良，靈君以亡。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震左，坎右，艮手為指麾，坎為邪淫，震富，故曰侈靡。艮為執、為節，震為君，坎為棺槨，故曰亡靈。君謂陳靈公通夏姬，為夏徵舒所弒也。○君，宋元本作公，依汲古。</p><h3 id="豐之賁" tabindex="-1">豐之賁 <a class="header-anchor" href="#豐之賁" aria-label="Permalink to “豐之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>日中為市，各持所有。交易資賄，函珠懷寶，心悅歡喜。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《升》。</p><h3 id="豐之剝" tabindex="-1">豐之剝 <a class="header-anchor" href="#豐之剝" aria-label="Permalink to “豐之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>山沒丘浮，陸為水魚，燕雀無廬。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為山丘，在坤水上，故曰山沒丘浮。艮為陸，坤為水、為魚，故陸為水魚。艮為廬，伏兌為燕雀，水大，故廬圮也。</p><h3 id="豐之復" tabindex="-1">豐之復 <a class="header-anchor" href="#豐之復" aria-label="Permalink to “豐之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>馬服長股，宜行善市。蒙佑諧偶，獲利五倍。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為馬，伏巽為長、為股。服，猶駕也。巽為市，馬而長股，必得善市，伏巽為市、為利、為倍，巽卦數五，故曰獲利五倍。</p><h3 id="豐之無妄" tabindex="-1">豐之無妄 <a class="header-anchor" href="#豐之無妄" aria-label="Permalink to “豐之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>三狸捕鼠，遮遏前後。死於圜城，不能脫走。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>詳《離》之《遯》。圜城，宋本作環城，元本作環域，依汲古。</p><h3 id="豐之大畜" tabindex="-1">豐之大畜 <a class="header-anchor" href="#豐之大畜" aria-label="Permalink to “豐之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>鬼舞國社，歲樂民喜。臣忠於君，子孝於父。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>伏坤為鬼、為國、為社，震為舞，乾為年歲，坤為民，震為喜樂，乾為君父，艮為臣，震為子，坤順，故曰孝、曰忠。</p><h3 id="豐之頤" tabindex="-1">豐之頤 <a class="header-anchor" href="#豐之頤" aria-label="Permalink to “豐之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>慈母望子，遙思不已。久客外野，我心悲苦。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>詳《鹹》之《旅》。</p><h3 id="豐之大過" tabindex="-1">豐之大過 <a class="header-anchor" href="#豐之大過" aria-label="Permalink to “豐之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>雨師娶婦，黃巖季女。成禮既婚，相呼南去。膏澤田裡，年歲大喜。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>校詳本林比。</p><h3 id="豐之坎" tabindex="-1">豐之坎 <a class="header-anchor" href="#豐之坎" aria-label="Permalink to “豐之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>兩狗同室，相嚙爭食。枉矢西流，射我暴國。高宗鬼方，三年乃服。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>艮為狗、為室，中爻正反艮，故曰兩狗同室。震為口、為食，正反震相對，故曰相嚙、曰爭食。坎為矢、為曲屈，故曰枉矢。枉矢，星名。《史記天官書》枉矢如大流星。坎位西，故曰西流。震為射，艮為國，震健躁，故曰暴國。震為宗，坎為鬼，震為年，數三，故曰三年。○兩，宋元本作百，依汲古。同，汲古作圍，嚙作咬，茲依宋元本。</p><h3 id="豐之離" tabindex="-1">豐之離 <a class="header-anchor" href="#豐之離" aria-label="Permalink to “豐之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>早霜晚雪，傷禾害麥。損功棄力，飢無可食。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳《離》之《蠱》。</p><h3 id="豐之鹹" tabindex="-1">豐之鹹 <a class="header-anchor" href="#豐之鹹" aria-label="Permalink to “豐之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>腐臭所在，青蠅集聚。變白為黑，敗亂邦國。君為臣逐，失其寵祿。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>巽為腐臭、為青蠅。青蠅，《小雅》篇名戒王信讒也。伏坤為集聚，巽為白、為敗亂，艮黔，故曰黑。艮為邦國、為臣，乾為君，在艮外，故曰君為臣逐。乾為寵祿，兌毀折，故曰失。○第三句宋本作變●白黑，元本作辯●白黑，●疑為更訛，依汲古。</p><h3 id="豐之恆" tabindex="-1">豐之恆 <a class="header-anchor" href="#豐之恆" aria-label="Permalink to “豐之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>牽羊不前，與心戾旋。聞言不信，誤紿丈人。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>兌為羊，震為後，故曰不前。伏坤為心，正反兌，故曰戾旋。戾旋，不合也。兌口為言，正反兌，故曰不信。兌為耳，故曰聞。《夬九四》聞言不信，以兌口與乾言背也。恆二至四與夬體同也，不信，故曰誤紿。震為丈人。○元本作牽羊不前。與心戾旋。聞言語不信，誤紹丈人。今依宋本、汲古。</p><h3 id="豐之遯" tabindex="-1">豐之遯 <a class="header-anchor" href="#豐之遯" aria-label="Permalink to “豐之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>甘忍利害，還相剋賊。商子酷刑，鞅喪厥身。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>互巽為利，巽隕落，故曰害。巽伏，故曰賊。言甘於刻害，還自賊也。巽為商賈，故曰商子。伏坤為酷，坤殺，故曰酷刑。坤為身、為喪，故曰鞅喪厥身，言商鞅用酷刑終自害也。巽為繩、為鞅，《說文》鞅，頸系也。○害，元本作瘧，酷作造，鞅作鞭，均依宋本、汲古。賊，宋本、汲古作敵，依元本。</p><h3 id="豐之大壯" tabindex="-1">豐之大壯 <a class="header-anchor" href="#豐之大壯" aria-label="Permalink to “豐之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>刲羊不當，血少無羹。女執空筐，不得採桑。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>採桑，汲古作桑根，依《隨》之《艮》校，元本下三句作女執空筐，兔跛鹿踦，緣山墜墮，依汲古。</p><h3 id="豐之晉" tabindex="-1">豐之晉 <a class="header-anchor" href="#豐之晉" aria-label="Permalink to “豐之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>嚙嚙，貧鬼相責。無有歡怡，一日九結。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《震》之《既濟》。</p><h3 id="豐之明夷" tabindex="-1">豐之明夷 <a class="header-anchor" href="#豐之明夷" aria-label="Permalink to “豐之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>兩足四翼，飛入嘉國。寜我伯姊，與母相得。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《同人》。</p><h3 id="豐之家人" tabindex="-1">豐之家人 <a class="header-anchor" href="#豐之家人" aria-label="Permalink to “豐之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>文山紫芝，雍梁朱草。生長和氣，王以為寶。公屍侑食，福祿來處。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《夬》。文，宋元本作天，依汲古。</p><h3 id="豐之睽" tabindex="-1">豐之睽 <a class="header-anchor" href="#豐之睽" aria-label="Permalink to “豐之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>絕世遊魂，福祿不存。精神渙散，離其躬身。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>互坎為魂，兌決，故曰絕。震為福祿、為精神，兌折震，故曰福祿不存、曰精神渙散。艮為身，艮伏，故曰離。京房以七世卦為遊魂卦，《繫辭》雲：精氣為物，遊魂為變，鄭雲九六為遊魂。</p><h3 id="豐之蹇" tabindex="-1">豐之蹇 <a class="header-anchor" href="#豐之蹇" aria-label="Permalink to “豐之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>北辰紫宮，衣冠立中。含和建德，常受大福。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《解》。和，宋本、汲古作弘，依元本。</p><h3 id="豐之解" tabindex="-1">豐之解 <a class="header-anchor" href="#豐之解" aria-label="Permalink to “豐之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>伯蹇叔盲，莫為守裝。失我衣裘，代爾陰鄉。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《鼎》之《離》。盲，宋元本作喑，為作與，裝作株，今依汲古。</p><h3 id="豐之損" tabindex="-1">豐之損 <a class="header-anchor" href="#豐之損" aria-label="Permalink to “豐之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>兩女共室，心不聊食。首髪如蓬，憂常在中。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《艮》之《剝》。首艮象，汲古作亂，非，依宋元本。</p><h3 id="豐之益" tabindex="-1">豐之益 <a class="header-anchor" href="#豐之益" aria-label="Permalink to “豐之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>去辛就蓼，毒愈酷甚。避穽遇坑，憂患日生。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>《說文》蓼，辛菜。震為草莽，故曰蓼。震納庚，巽納辛，庚辛，西方，味辛，故曰去辛就蓼。《詩周頌》自求辛螫，未堪家多難，予又集於蓼。坤為毒、為酷，兌為穽，兌伏，故曰避穽。坤為淵，故曰坑、曰憂患。震生，艮為日，故曰日生。○酷，宋元本作苦，依汲古。</p><h3 id="豐之夬" tabindex="-1">豐之夬 <a class="header-anchor" href="#豐之夬" aria-label="Permalink to “豐之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>初病終兇，季為死喪，不見光明。通《剝》。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>坤為病，坤死，故曰兇、曰喪。艮為終、為季、為光明，坤黑，故不見。</p><h3 id="豐之姤" tabindex="-1">豐之姤 <a class="header-anchor" href="#豐之姤" aria-label="Permalink to “豐之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>三鳥飛來，是我逢時。俱行先至，多得大利。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《大有》。</p><h3 id="豐之萃" tabindex="-1">豐之萃 <a class="header-anchor" href="#豐之萃" aria-label="Permalink to “豐之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>鹿食山草，不思邑里，雖久無咎。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>伏震為鹿，兌食，艮山，巽草，坤為思、為思、為邑里，艮為久。</p><h3 id="豐之升" tabindex="-1">豐之升 <a class="header-anchor" href="#豐之升" aria-label="Permalink to “豐之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>羊腸九縈，相推稍前。止須王孫，乃能上天。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《師》。</p><h3 id="豐之困" tabindex="-1">豐之困 <a class="header-anchor" href="#豐之困" aria-label="Permalink to “豐之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>管仲遇桓，得其願歡。膠目啟牢，振冠無憂。笑戲不莊，空言妄行。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>膠目二句依《明夷》之《旅》校。宋本作膠目振冠，冠帶無憂，元本作膠牢振寇，寇帶無憂，汲古作膠目膠口。</p><h3 id="豐之井" tabindex="-1">豐之井 <a class="header-anchor" href="#豐之井" aria-label="Permalink to “豐之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>桀蹠並處，民困愁苦。旅行遲遲，留連齊魯。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《復》之《離》。</p><h3 id="豐之革" tabindex="-1">豐之革 <a class="header-anchor" href="#豐之革" aria-label="Permalink to “豐之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>魂孤無室，銜指不食。盜張民饋，見敵失肉。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>民饋，宋元本作民餌，汲古作氏饋，今民字從宋元本，饋從汲古。乾為魂，巽為寡，故曰魂孤。坎為室，坎伏，故無室。兌為銜、為食，伏艮為指，伏坤為閉，故不食。伏坎為盜，坤為民，民畏盜故饋之。坎為肉，坤喪，故失肉。</p><h3 id="豐之鼎" tabindex="-1">豐之鼎 <a class="header-anchor" href="#豐之鼎" aria-label="Permalink to “豐之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>讒言亂國，覆是為非。伯奇乖離，恭子憂哀。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《巽》之《觀》。</p><h3 id="豐之震" tabindex="-1">豐之震 <a class="header-anchor" href="#豐之震" aria-label="Permalink to “豐之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>衛侯東遊，惑於少姬。亡我考妣，久迷不來。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《升》。</p><h3 id="豐之艮" tabindex="-1">豐之艮 <a class="header-anchor" href="#豐之艮" aria-label="Permalink to “豐之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>雞鳴同興，思配無家。執佩持鳧，莫使致之。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《漸》之《鼎》。配，宋元本作邪，佩作佩，依汲古。</p><h3 id="豐之漸" tabindex="-1">豐之漸 <a class="header-anchor" href="#豐之漸" aria-label="Permalink to “豐之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>義不勝情，以欲自縈。覬利危躬，摧角折頸。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《豐》。</p><h3 id="豐之歸妹" tabindex="-1">豐之歸妹 <a class="header-anchor" href="#豐之歸妹" aria-label="Permalink to “豐之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>臣尊主卑，權力日衰。侵奪無光，三家逐公。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>詳《升》之《巽》。權，宋元本作擁，依汲古。</p><h3 id="豐之豐" tabindex="-1">豐之豐 <a class="header-anchor" href="#豐之豐" aria-label="Permalink to “豐之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>諸孺行賈，經涉山阻。與狄為市，不憂危殆，利得十倍。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>孺，《說文》乳子也。震為子，兌少。諸，《爾雅釋詁》諸諸便便辯也。震為言，故曰諸孺。震為商賈，故曰行賈。伏艮為山，兌為狄，按：《呂覽》有西翟，翟狄通用。《周語》自竄於戒［當作戎］翟之間是也。《爾雅》註稱東夷、西戎、北狄，然觀各書，戎狄於西北實不分，故林以兌西為狄也。巽為市，坎為憂，坎伏，故不憂不殆。巽為利、為倍，兌數十，故曰十倍。林意言者孺行賈當危殆，而竟得利也。○山，宋元本作火，狄作杖，均依汲古。</p><h3 id="豐之旅" tabindex="-1">豐之旅 <a class="header-anchor" href="#豐之旅" aria-label="Permalink to “豐之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>叔仲善賈，與喜為市。不憂危殆，利得十倍。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。艮為叔，坎為仲，震為商賈、為喜，巽為市。坎為危殆、為憂，震解，故不憂。巽為利、為倍，兌數十，故曰十倍。</p><h3 id="豐之巽" tabindex="-1">豐之巽 <a class="header-anchor" href="#豐之巽" aria-label="Permalink to “豐之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>六蛇奔走，俱入茂草。驚於長路，畏懼啄口。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《井》之《兌》。</p><h3 id="豐之兌" tabindex="-1">豐之兌 <a class="header-anchor" href="#豐之兌" aria-label="Permalink to “豐之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>水壞我裡，東流為海。鳧龜歡囂，不得安居。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《兌》。龜，宋元本作鼃，依汲古。得，汲古作可，依宋元本。</p><h3 id="豐之渙" tabindex="-1">豐之渙 <a class="header-anchor" href="#豐之渙" aria-label="Permalink to “豐之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>飛不遠去，卑斯內侍，祿養未富。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>互震為飛，艮止，故飛不遠去。互艮為斯，《旅初六》雲旅瑣瑣，斯其所，註：斯，賤役也，故曰卑斯。</p><h3 id="豐之節" tabindex="-1">豐之節 <a class="header-anchor" href="#豐之節" aria-label="Permalink to “豐之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>陰變為陽，女化為男。治道大通，君臣相承。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《離》。</p><h3 id="豐之中孚" tabindex="-1">豐之中孚 <a class="header-anchor" href="#豐之中孚" aria-label="Permalink to “豐之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>踐履危難，脫厄去患。入福喜門，見誨大君。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>詳《震》之《家人》。</p><h3 id="豐之小過" tabindex="-1">豐之小過 <a class="header-anchor" href="#豐之小過" aria-label="Permalink to “豐之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>罟密網縮，動益蹶急，困不得息。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>伏大離為網罟。縮，朿縛也，卦象似之。互大坎，故曰蹶、曰困。○罟網，汲古作網綱，蹶作蹙，均依宋元本。</p><h3 id="豐之既濟" tabindex="-1">豐之既濟 <a class="header-anchor" href="#豐之既濟" aria-label="Permalink to “豐之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>負牛上山，力劣行難。烈風雨雪，遮遏我前，中道復還。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《無妄》。汲古多憂者得歡四字，依宋元本。○此用豐象。</p><h3 id="豐之未濟" tabindex="-1">豐之未濟 <a class="header-anchor" href="#豐之未濟" aria-label="Permalink to “豐之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>喁喁嘉草，思降甘雨。景風升上，霑洽時澍，生我禾稼。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此仍用豐象。兌口，震言，故曰喁喁。喁，嚮慕之義。震為嘉草、為禾稼，巽風，坎雨，坎伏，故曰思降。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
